WHO = {'column': [('uneyeaeli', 203506), ('qum', 203506), ('qum', 203570), ('thivi', 0), ('mulcefclysen', 203698), ('mueflhili', 204271), ('aprilclysen', 0), ('muefeben', 204335)], 'manor': [('mueflfelsof', 203698), ('mulcefclysen', 204335), ('muefeben', 0), ('muefleeova', 0), ('psiloclysen', 206949), ('mueflfelsof', 0), ('mulcefclysen', 0), ('psiloclysen', 0)], 'tree': [('brifeeaeli', 204271), ('alphaffools', 204523), ('alphaffools', 205481), ('mueflfldum', 0), ('renmaeli', 207838), ('muelldum', 208350), ('aprilfools', 209050), ('renmaeli', 209050)], 'bridge': [('alphaffelsof', 0), ('alphaffelsof', 204523), ('alphaffelsof', 205737), ('alphafoldmicro', 206436), ('alphaffelsof', 213827), ('alphafolsof', 214975), ('alphaffelsof', 215864), ('alphaffelsof', 217202)], 'temple': [('mulceflhili', 0), ('mueflfelsof', 205481), ('mueflfeben', 0), ('quhlyelfldum', 206949), ('mulceffelsof', 209558), ('quldmeeben', 209813), ('mueflfldum', 210898), ('mueflfelsof', 216949)], 'tower': [('quchepy', 205035), ('einsof', 210706), ('muefleeova', 0), ('uneyeefelsof', 212108), ('mulcefldmicr', 213510), ('mulceflhili', 213827), ('untemva', 214275), ('quchepy', 216501)], 'castle': [('quldmelfldum', 206949), ('quldmelfldum', 0)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW340(OracleReleaseRuntimeW339):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
